import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/pt/provedores-detalhe.png",d="/pro-agent-hub-installer/capturas/pt/modelos-detalhe.png",h=JSON.parse('{"title":"Provedores e modelos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/provedores-modelos.md","filePath":"pt/interface/provedores-modelos.md","lastUpdated":1787856241000}'),n={name:"pt/interface/provedores-modelos.md"};function i(m,e,p,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="provedores-e-modelos" tabindex="-1">Provedores e modelos <a class="header-anchor" href="#provedores-e-modelos" aria-label="Permalink to &quot;Provedores e modelos&quot;">​</a></h1><p>É por aqui que se começa. Um agente sem modelo não salva, e um modelo sem provedor não existe.</p><h2 id="provedores" tabindex="-1">Provedores <a class="header-anchor" href="#provedores" aria-label="Permalink to &quot;Provedores&quot;">​</a></h2><p><img src="'+s+'" alt="provedores-detalhe"></p><p>Um <strong>provedor</strong> é de onde a inteligência vem: OpenAI, Anthropic, Google ou um Ollama rodando na sua própria máquina. O cadastro guarda o tipo, o endereço e a chave de API.</p><p><strong>A chave viaja no arquivo de exportação</strong>, cifrada — mas com uma chave padrão que está no código, o que protege da leitura casual e não de alguém decidido. Vale saber disso antes de mandar um export para alguém. Ver <a href="/pro-agent-hub-installer/pt/interface/administracao#importar-e-exportar">Importar e exportar</a>.</p><p><strong>Ollama não pede chave.</strong> Ele roda junto da instalação e o endereço padrão já vem preenchido. É o caminho para não depender de serviço pago nem mandar dados para fora.</p><h2 id="modelos" tabindex="-1">Modelos <a class="header-anchor" href="#modelos" aria-label="Permalink to &quot;Modelos&quot;">​</a></h2><p><img src="'+d+'" alt="modelos-detalhe"></p><p>Um <strong>modelo</strong> é um modelo específico de um provedor — <code>gpt-4o</code> da OpenAI, <code>nomic-embed-text</code> do Ollama. O mesmo nome pode existir em provedores diferentes, e a plataforma os trata como registros distintos.</p><p>Duas marcações decidem onde ele pode ser usado:</p><ul><li><strong>Uso em chat</strong> — pode ser o cérebro de um agente, time ou planejador.</li><li><strong>Uso em embedding</strong> — pode vetorizar um conhecimento.</li></ul><p>Um modelo de embedding tem <strong>dimensão</strong>, e ela precisa bater com a do vetor já gravado. Trocar o modelo de embedding de um conhecimento que já foi vetorizado exige recarga completa — a coleção é recriada com a dimensão nova.</p><h3 id="preco-e-limites" tabindex="-1">Preço e limites <a class="header-anchor" href="#preco-e-limites" aria-label="Permalink to &quot;Preço e limites&quot;">​</a></h3><p>O cadastro aceita preço por milhão de tokens (entrada e saída) e tetos de consumo diário e mensal, por tokens ou por custo.</p><p><strong>O teto tem dois estágios</strong>, e vale entender a diferença antes de configurar:</p><ul><li>Ao cruzar o <strong>percentual de alerta</strong>, a plataforma avisa os usuários master por e-mail e segue funcionando.</li><li>Ao cruzar o <strong>limite</strong>, com <em>bloquear</em> ligado, as execuções daquele modelo passam a ser recusadas.</li></ul><p>Sem preço cadastrado não há custo para acompanhar — só contagem de tokens. O acompanhamento fica em <a href="/pro-agent-hub-installer/pt/interface/administracao#consumo-de-tokens">Consumo de tokens</a>.</p>',18)])])}const v=o(n,[["render",i]]);export{h as __pageData,v as default};
